import type { ReactNode } from 'react'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

'use server'

import { refresh } from 'next/cache'

let notificationsEnabled = false

export async function getNotificationPreference(): Promise<boolean> {
  return notificationsEnabled
}

export async function toggleNotifications(): Promise<void> {
  notificationsEnabled = !notificationsEnabled
  refresh()
}

import {
  getNotificationPreference,
  toggleNotifications,
} from './actions'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications: <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          {notificationsEnabled ? 'Turn Off' : 'Turn On'} Notifications
        </button>
      </form>
    </main>
  )
}
